export function originalShotState(frame, fps) {
  const seconds = frame / fps;
  const t = Math.max(0, Math.min(1, seconds / 0.6));
  const eased = 1 - (1 - t) ** 3;
  return { opacity: eased, translateY: 18 * (1 - eased), caption: seconds < 3 ? 'Make the next step visible' : 'Give it an owner' };
}
